function count_rows($pdo,$table){ return (int)$pdo->query("SELECT COUNT(*) FROM `$table`")->fetchColumn(); }
$totalSales=(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status='Completed'")->fetchColumn();
$orders=count_rows($pdo,'orders'); $customers=count_rows($pdo,'customers'); $stock=(int)$pdo->query("SELECT COALESCE(SUM(stock),0) FROM products")->fetchColumn();
$recent=$pdo->query("SELECT o.*, c.full_name FROM orders o LEFT JOIN customers c ON c.id=o.customer_id ORDER BY o.id DESC LIMIT 5")->fetchAll();
