$title=ucwords(str_replace('_',' ',$page));
function rows_table($rows,$headers){ echo '<div class="table-wrap"><table><thead><tr>'; foreach($headers as $h) echo '<th>'.e($h).'</th>'; echo '</tr></thead><tbody>'; foreach($rows as $r){echo '<tr>'; foreach($r as $v) echo '<td>'.e($v).'</td>'; echo '</tr>';} if(!$rows) echo '<tr><td colspan="'.count($headers).'" class="empty">No records yet.</td></tr>'; echo '</tbody></table></div>'; }
?>
